    /** Spellings seen in slugs / English names -> map key. */
    private const ALIASES = [
        'barisal' => 'barishal',
        'barishal' => 'barishal',
        'chittagong' => 'chattogram',
        'chattogram' => 'chattogram',
        'chattagram' => 'chattogram',
        'dhaka' => 'dhaka',
        'khulna' => 'khulna',
        'mymensingh' => 'mymensingh',
        'mymensing' => 'mymensingh',
        'rajshahi' => 'rajshahi',
        'rangpur' => 'rangpur',
        'sylhet' => 'sylhet',
    ];

    public static function viewBox(): string
    {
        return '0 0 '.self::WIDTH.' '.self::HEIGHT;
    }

    /** Map key for a division, matched on its slug first and then its English name; null when unknown. */
    public static function keyFor(?string $slug, ?string $nameEn = null): ?string
    {
        foreach ([$slug, $nameEn] as $raw) {
            $norm = preg_replace('/[^a-z]/', '', strtolower((string) $raw));
            $norm = preg_replace('/division$/', '', (string) $norm);

            if ($norm !== '' && isset(self::ALIASES[$norm])) {
                return self::ALIASES[$norm];
            }
        }

        return null;
    }
}
